dtsPropsFor.Button:
/** 색상 변형. 기본값 "primary". */
  variant?: "primary" | "secondary" | "success" | "danger";
  /** 컨테이너 폭을 모두 차지한다. 기본값 false. */
  fullWidth?: boolean;
  children?: React.ReactNode;
  onClick?: React.MouseEventHandler<HTMLButtonElement>;
  disabled?: boolean;
  type?: "button" | "submit" | "reset";
  className?: string;

dtsPropsFor.ActionButton:
/** 목록 헤더의 텍스트형 액션(모두 읽음/전체 삭제/새로고침 등). */
  children?: React.ReactNode;
  onClick?: React.MouseEventHandler<HTMLButtonElement>;
  disabled?: boolean;
  type?: "button" | "submit" | "reset";
  className?: string;

dtsPropsFor.EmptyState:
/** 이모지 1자를 권장한다 (예: "🔔", "⏳", "⚠️", "📋", "🎯"). */
  icon: string;
  title: string;
  desc: React.ReactNode;

dtsPropsFor.FormField:
/** 입력 위에 붙는 라벨. */
  label: string;
  /** 입력 아래 보조 설명. 없으면 줄 자체가 렌더되지 않는다. */
  hint?: string;
  value?: string | number;
  onChange?: React.ChangeEventHandler<HTMLInputElement>;
  type?: string;
  placeholder?: string;
  disabled?: boolean;

dtsPropsFor.ErrorBoundary:
/** 에러 시 렌더할 내용. reset으로 재시도(경계 재마운트)를 트리거한다. */
  fallback: (error: Error, reset: () => void) => React.ReactNode;
  /** 재시도 시 상위(예: 쿼리 캐시) 리셋 훅. */
  onReset?: () => void;
  children: React.ReactNode;

dtsPropsFor.NotificationCard:
notification: {
    id: string;
    issue_key: string;
    summary: string;
    notification_type: "Mention" | "Assigned";
    message: string;
    /** ISO 8601 문자열. 카드에는 상대시간으로 표시된다. */
    timestamp: string;
    url: string;
    read: boolean;
  };
  onClick: (notification: NotificationCardProps["notification"]) => void;

dtsPropsFor.TicketCard:
ticket: {
    key: string;
    summary: string;
    status: string;
    reporter: string;
    /** ISO 8601 문자열. 카드에는 상대시간으로 표시된다. */
    updated: string;
    url: string;
  };
  /** 좌측 아이콘. 미배정 목록은 "📋", 내 담당 목록은 "🎯"를 쓴다. */
  icon: string;
  /** 보고자 줄 표시 여부. */
  showReporter: boolean;
  onClick: (ticket: TicketCardProps["ticket"]) => void;
